import React, { HTMLAttributes, PropsWithChildren, ReactNode } from "react";
import clsx from "clsx";
import { Header as HeaderStyles } from "@airbus/styles";
import { Menu as MenuIcon } from "@airbus/icons/react";
import {
  createUseStyles,
  ColorModeProvider,
  useTheme,
} from "../../lib/styling";
import useMediaQuery from "../../lib/hooks/useMediaQuery";
import { ThemeMode } from "../helperTypes";
import IconButton from "../IconButton";
import Tabs from "../Tabs";
import { CommonProps } from "../helperTypes";

// TODO reimplement prominent/static/mobile props later ?

type Props = PropsWithChildren<{
  /** Application name */
  appName?: string | ReactNode;
  /** Callback fired when the Logo or AppName is clicked */
  onHomeClick?: () => void;
  /** Callback fired when the Menu button is clicked */
  onMenuButtonClick?: () => void;
  /** Show Menu icon button */
  showMenuButton?: boolean;
  /**
   * Theme/color that will impact children variants
   * @default "dark"
   */
  theme?: ThemeMode;
}>;

export type HeaderProps = Props & CommonProps;

const useStyles = createUseStyles(HeaderStyles, "header");

const Header = ({
  appName,
  className,
  children,
  onHomeClick,
  onMenuButtonClick,
  showMenuButton,
  theme = "light",
  ...rest
}: HeaderProps) => {
  const {
    responsive: { breakpoint },
  } = useTheme();
  const mqMaxSM = useMediaQuery(`(max-width: ${breakpoint.sm}px)`);

  return (
    <ColorModeProvider mode={theme}>
      <HeaderWrapper
        className={className}
        showMenuButton={showMenuButton}
        theme={theme}
        {...rest}
      >
        <HeaderHome appName={appName} onHomeClick={onHomeClick} />

        {React.Children.map(children, (child) => {
          if (!React.isValidElement(child)) return null;
          if (child.type !== Tabs) return child;

          // TABS props
          return React.cloneElement<any>(child, {
            ...(child.props as any),
            floating: true,
            scrollable: mqMaxSM,
            "aria-label": "navigation",
            variant: "negative",
          });
        })}

        {showMenuButton && (
          <IconButton
            variant="ghostNegative"
            onClick={onMenuButtonClick}
            aria-label="Open the menu"
          >
            <MenuIcon />
          </IconButton>
        )}
      </HeaderWrapper>
    </ColorModeProvider>
  );
};
export default Header;

type HeaderWrapperProps = Pick<
  HeaderProps,
  "children" | "showMenuButton" | "theme"
> &
  HTMLAttributes<HTMLDivElement>;

// separated component to ensure useStyles gets
// correct theme context value from ColorModeProvider
const HeaderWrapper = ({
  children,
  className,
  showMenuButton,
  theme,
  ...rest
}: HeaderWrapperProps) => {
  const classes = useStyles();
  return (
    <div
      className={clsx(
        className,
        classes.root,
        classes[`_${theme}`],
        showMenuButton && classes._nopadding
      )}
      {...rest}
    >
      {children}
    </div>
  );
};

type HeaderHomeProps = Pick<HeaderProps, "appName" | "onHomeClick">;

const HeaderHome = ({ appName, onHomeClick }: HeaderHomeProps) => {
  const classes = useStyles();
  const hasHomeClick = onHomeClick !== undefined;
  const LogoAppname = () => (
    <>
      <div className={classes.logo} />
      <h1 className={classes.appname}>{appName}</h1>
    </>
  );
  if (hasHomeClick) {
    return (
      <div onClick={onHomeClick} className={classes.home} role="button" aria-label="Home">
        <LogoAppname />
      </div>
    );
  }
  return <LogoAppname />;
};
